$('task-form').onsubmit=async e=>{e.preventDefault();const name=$('task-name').value.trim(),goal=Number($('task-goal').value);if(!name||!Number.isInteger(goal)||goal<1||goal>1440)return;try{const id=editingTask||uid();await change(s=>{const existing=s.tasks.find(t=>t.id===id);const fields={name,goal,groupId:$('task-group').value,tag:$('task-tag').value};if(existing)Object.assign(existing,fields);else s.tasks.push({id,...fields,day:dateKey(),deleted:false})});closeDialog('task-dialog');if(editingTask)openTimer(id)}catch(e){$('form-error').textContent=e.message;$('form-error').hidden=false}};
function openTimer(id){selectedId=id;openDialog('timer-dialog');renderTimer()}
function renderTimer(){const t=state.tasks.find(t=>t.id===selectedId);if(!t){closeDialog('timer-dialog');return}const seconds=taskSeconds(t.id),active=running(),isRunning=active?.taskId===t.id,category=taskCategory(t);$('timer-category').textContent=category;$('timer-category').hidden=!category;$('timer-name').textContent=t.name;$('timer-clock').textContent=clock(seconds);$('timer-toggle').textContent=isRunning?'Ⅱ Pause & save':seconds>0?'▶ Continue':'▶ Start';$('timer-toggle').disabled=storageBlocked||!!t.deleted||!!t.finishedAt;$('timer-toggle').hidden=!!t.finishedAt;$('finish-task').hidden=!!t.deleted;$('finish-task').textContent=t.finishedAt?'↶ Unfinish task':'✓ Finish task';$('finish-task').disabled=storageBlocked;$('archive-task').hidden=taskProgress(t).completedAt===null||!!t.deleted||!!t.archived;$('archive-task').disabled=storageBlocked;$('timer-note').textContent=t.finishedAt?'Task finished. Your recorded time is saved.':active&&!isRunning?`Starting this pauses ${state.tasks.find(x=>x.id===active.taskId)?.name||'your other timer'}.`:isRunning?'Keep this moment for yourself.':'Pick up right where you left off.';$('timer-goal').textContent=duration(t.goal*60);$('timer-progress').value=Math.min(100,seconds/(t.goal*60)*100);$('goal-remaining').textContent=t.finishedAt?'Finished with '+duration(seconds)+' invested.':seconds>=t.goal*60?'Your intention is met. Any extra time is yours.':`${duration(Math.ceil((t.goal*60-seconds)/60)*60)} left for your intention.`;$('delete-task').hidden=!!t.deleted;$('saved-status').textContent=isRunning?'Keeps running when you close this':'Your time is saved';document.title=isRunning?`${clock(seconds)} · ${t.name} — MeeeMe`:'MeeeMe · A little time for yourself'}
$('timer-toggle').onclick=async()=>{try{await change(s=>{const t=s.tasks.find(t=>t.id===selectedId);if(!t||t.deleted||t.finishedAt)return;const active=s.sessions.find(x=>x.ended===null),now=Date.now();if(active){active.ended=Math.max(now,active.started);if(active.taskId===selectedId)return}s.sessions.push({id:uid(),taskId:selectedId,started:now,ended:null})})}catch{}};
function finishTask(data,id,now=Date.now()){const task=data.tasks.find(t=>t.id===id);if(!task||task.deleted||task.finishedAt)return;const active=data.sessions.find(s=>s.taskId===id&&s.ended===null);if(active)active.ended=Math.max(now,active.started);task.finishedAt=now}
function unfinishTask(data,id){const task=data.tasks.find(t=>t.id===id);if(task&&!task.deleted)delete task.finishedAt}
$('finish-task').onclick=async()=>{try{let reopened=false;await change(s=>{const task=s.tasks.find(t=>t.id===selectedId);if(task?.finishedAt){unfinishTask(s,selectedId);reopened=true}else finishTask(s,selectedId)});if(!reopened)closeDialog('timer-dialog')}catch{}};
function archiveTask(data,id,now=Date.now()){const task=data.tasks.find(t=>t.id===id);if(!task||task.deleted)return;task.archived=true;const active=data.sessions.find(s=>s.taskId===id&&s.ended===null);if(active)active.ended=Math.max(now,active.started)}
$('archive-task').onclick=async()=>{try{await change(s=>archiveTask(s,selectedId));closeDialog('timer-dialog')}catch{}};
$('edit-task').onclick=()=>{const t=state.tasks.find(t=>t.id===selectedId);closeDialog('timer-dialog');openTask(t)};
function confirm(title,message,label,action){$('confirm-title').textContent=title;$('confirm-message').textContent=message;$('confirm-ok').textContent=label;confirmAction=action;openDialog('confirm-dialog')}
$('confirm-cancel').onclick=()=>closeDialog('confirm-dialog');$('confirm-ok').onclick=async()=>{try{await confirmAction?.();closeDialog('confirm-dialog')}catch{}};
$('delete-task').onclick=()=>{const t=state.tasks.find(t=>t.id===selectedId);confirm('Remove this task?','It will leave today’s list. Any time you have recorded stays in your weekly history.','Remove',async()=>{await change(s=>{const task=s.tasks.find(x=>x.id===selectedId);if(task)task.deleted=true;const active=s.sessions.find(x=>x.taskId===selectedId&&x.ended===null);if(active)active.ended=Math.max(Date.now(),active.started)});closeDialog('timer-dialog')})};
function renderColorChoices(){const choices=$('group-color-choices');choices.replaceChildren();groupPalette.forEach((color,index)=>{const button=el('button','color-swatch');button.type='button';button.style.backgroundColor=color;button.title=groupColorNames[index];button.setAttribute('aria-label',groupColorNames[index]);button.setAttribute('aria-pressed',String($('group-color').value.toLowerCase()===color));button.onclick=()=>{$('group-color').value=color;renderColorChoices()};choices.append(button)})}
function renderGroups(){const select=$('manage-group');select.replaceChildren(new Option('Create a new group',''));for(const g of state.groups)select.add(new Option(g.name,g.id));select.value=editingGroup||'';$('group-picker').hidden=!state.groups.length;renderColorChoices();syncDropdown('manage-group')}
function resetGroupForm(){editingGroup=null;$('group-form').reset();$('group-color').value=groupPalette[state.groups.length%groupPalette.length];$('manage-group').value='';$('save-group').textContent='Create group';$('cancel-group-edit').hidden=true;$('group-error').hidden=true;renderColorChoices();syncDropdown('manage-group')}
$('manage-group').onchange=()=>{const g=state.groups.find(g=>g.id===$('manage-group').value);if(!g){resetGroupForm();return}editingGroup=g.id;$('group-name').value=g.name;$('group-tags').value=g.tags.join(', ');$('group-color').value=groupColor(g.id);$('save-group').textContent='Save group';$('cancel-group-edit').hidden=false;$('group-error').hidden=true;renderColorChoices()};
$('cancel-group-edit').onclick=resetGroupForm;
$('group-form').onsubmit=async e=>{e.preventDefault();const name=$('group-name').value.trim(),color=$('group-color').value,tags=[...new Set($('group-tags').value.split(',').map(t=>t.trim()).filter(Boolean))];if(!name)return;if(!/^#[0-9a-f]{6}$/i.test(color))return;if(tags.some(t=>t.length>50)){ $('group-error').textContent='Keep each activity tag under 50 characters.';$('group-error').hidden=false;return}try{const id=editingGroup||uid();await change(s=>{if(s.groups.some(g=>g.id!==id&&g.name.toLowerCase()===name.toLowerCase()))throw new Error('That group already exists. Edit it to add tags.');const g=s.groups.find(g=>g.id===id);if(g)Object.assign(g,{name,tags,color});else s.groups.push({id,name,tags,color})});resetGroupForm();if($('task-dialog').open)groupOptions(id,tags[0]||'')}catch(e){$('group-error').textContent=e.message;$('group-error').hidden=false}};
$('theme-button').onclick=()=>{renderThemeOptions();openDialog('theme-dialog')};
$('settings-button').onclick=()=>{resetGroupForm();renderGroups();openDialog('groups-dialog')};$('new-group-from-task').onclick=()=>{resetGroupForm();renderGroups();openDialog('groups-dialog')};
function switchView(view){$('today-view').hidden=view!=='today';$('week-view').hidden=view!=='week';for(const name of ['today','week']){const active=name===view;$(`${name}-tab`).classList.toggle('active',active);$(`${name}-tab`).setAttribute('aria-pressed',String(active))}render()}
$('today-tab').onclick=()=>switchView('today');$('week-tab').onclick=()=>switchView('week');$('add-button').onclick=()=>openTask();$('previous-week').onclick=()=>{weekOffset--;renderWeek()};$('next-week').onclick=()=>{if(weekOffset<0)weekOffset++;renderWeek()};$('task-group').onchange=()=>tagOptions();$('task-goal').oninput=updatePresets;document.querySelectorAll('[data-minutes]').forEach(b=>b.onclick=()=>{$('task-goal').value=b.dataset.minutes;updatePresets()});document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
window.addEventListener('storage',e=>{if(e.key===THEME_KEY){applyTheme(e.newValue||'light');return}if(e.key===KEY||e.key===null){try{state=read();storageBlocked=false;showError('');render()}catch(error){storageBlocked=true;showError(error.message)}}});window.addEventListener('focus',()=>{try{state=read();render()}catch{}});
let lastDay=dateKey();setInterval(()=>{const today=dateKey(),dayChanged=lastDay!==today;if(dayChanged){lastDay=today;filter='all'}if(running()||$('timer-dialog').open||dayChanged){renderToday();if(!$('week-view').hidden)renderWeek();if($('timer-dialog').open)renderTimer()}const active=running();if(active&&!$('timer-dialog').open){const t=state.tasks.find(t=>t.id===active.taskId);document.title=`${clock(taskSeconds(active.taskId))} · ${t?.name||'Focus'} — MeeeMe`}else if(!active&&!$('timer-dialog').open)document.title='MeeeMe · A little time for yourself'},1000);
